package app.moire.anniversary;
import android.app.*;import android.content.*;import android.media.RingtoneManager;import android.net.Uri;import android.os.*;import org.json.*;import java.text.*;import java.util.*;
public class MoireAlarm extends android.content.BroadcastReceiver {
 static final String PREF="moire_v24_alarms", ACTION="app.moire.anniversary.ALARM";
 static int requestCode(String id){return id.hashCode() & 0x7fffffff;}
 static PendingIntent pending(Context c,String id){Intent i=new Intent(c,MoireAlarm.class).setAction(ACTION).setData(Uri.parse("moire://alarm/"+Uri.encode(id)));return PendingIntent.getBroadcast(c,requestCode(id),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void sync(Context c,JSONArray alarms){try{JSONArray old=new JSONArray(c.getSharedPreferences(PREF,0).getString("rows","[]"));AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int k=0;k<old.length();k++){JSONObject x=old.optJSONObject(k);if(x!=null)am.cancel(pending(c,x.optString("id")));}c.getSharedPreferences(PREF,0).edit().putString("rows",alarms.toString()).apply();scheduleAll(c);}catch(Exception e){android.util.Log.e("MOIRE","sync alarm",e);}}
 static void scheduleAll(Context c){try{JSONArray a=new JSONArray(c.getSharedPreferences(PREF,0).getString("rows","[]"));for(int k=0;k<a.length();k++){JSONObject row=a.optJSONObject(k);if(row!=null)schedule(c,row);}}catch(Exception e){android.util.Log.e("MOIRE","schedule all",e);}}
 static void schedule(Context c,JSONObject row){try{JSONObject a=row.optJSONObject("alarm");if(a==null||!a.optBoolean("enabled"))return;String[] d=row.optString("date").split("-");if(d.length!=3)return;String[] t=a.optString("time","08:00").split(":");Calendar cal=Calendar.getInstance();cal.setLenient(false);cal.set(Integer.parseInt(d[0]),Integer.parseInt(d[1])-1,Integer.parseInt(d[2]),Integer.parseInt(t[0]),Integer.parseInt(t[1]),0);cal.set(Calendar.MILLISECOND,0);cal.add(Calendar.DAY_OF_MONTH,-a.optInt("offset",0));long now=System.currentTimeMillis();if(cal.getTimeInMillis()<=now&&row.optBoolean("repeat")&&"solar".equals(row.optString("calendarType"))){while(cal.getTimeInMillis()<=now)cal.add(Calendar.YEAR,1);}if(cal.getTimeInMillis()<=now)return;AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent pi=pending(c,row.optString("id"));if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);
 }catch(Exception e){android.util.Log.e("MOIRE","schedule one",e);}}
 static void channel(Context c){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel ch=new NotificationChannel("moire_alarm_v24","MOIRE 기념일 알람",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);nm.createNotificationChannel(ch);}
 @Override public void onReceive(Context c,Intent i){if(!ACTION.equals(i.getAction())){scheduleAll(c);return;}String id=i.getData()==null?"":i.getData().getLastPathSegment();try{JSONArray rows=new JSONArray(c.getSharedPreferences(PREF,0).getString("rows","[]"));for(int k=0;k<rows.length();k++){JSONObject row=rows.optJSONObject(k);if(row==null||!row.optString("id").equals(id))continue;JSONObject a=row.optJSONObject("alarm");channel(c);String title=row.optString("category","🎉")+" "+row.optString("name");Intent open=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,requestCode(id),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(c,"moire_alarm_v24").setSmallIcon(R.mipmap.ic_launcher).setContentTitle(title).setContentText("기념일 알람").setContentIntent(pi).setAutoCancel(true).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_HIGH);String sound=a==null?"default":a.optString("sound","default");if("silent".equals(sound))b.setSound(null);else {String uri=c.getSharedPreferences(PREF,0).getString("sound_uri","");Uri u="custom".equals(sound)&&!uri.isEmpty()?Uri.parse(uri):RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);b.setSound(u);}((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(requestCode(id),b.build());if(row.optBoolean("repeat"))schedule(c,row);break;}}catch(Exception e){android.util.Log.e("MOIRE","alarm fire",e);}}
 static void test(Context c){channel(c);Notification.Builder b=new Notification.Builder(c,"moire_alarm_v24").setSmallIcon(R.mipmap.ic_launcher).setContentTitle("MOIRE 알람 테스트").setContentText("알림 소리와 권한을 확인하세요").setAutoCancel(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(2400,b.build());}
}
